const final=document.createElement('div');final.id='onboardingAutoRules';final.className='hidden';final.innerHTML='<h3>Preparation preferences</h3><div class="grid2"><div><label for="obDailyLimit">Daily preparation limit</label><input id="obDailyLimit" type="number" min="1" max="50" value="5"></div><div><label for="obMatchThreshold">Minimum match score</label><input id="obMatchThreshold" type="number" min="50" max="100" value="85"></div></div><p class="meta" id="obAutoRulesSummary"></p>';$('autoAcknowledgement').before(final);const paint=paintOb;paintOb=function(){paint();const auto=$('obCtrl').value==='auto';final.classList.toggle('hidden',!auto);$('obAutoRulesSummary').textContent='Roles: '+(state.prefs.titles||'Not set')+' · Locations: '+(state.prefs.locations||'Not set')+' · Minimum salary: '+(state.prefs.minsal||'No minimum')+' · Exclusions: '+([$ ('apExCo').value,$('apExKw').value].filter(Boolean).join(', ')||'None set')+'. Manage additional rules in Agent.';};$('onboardingModes').addEventListener('change',paintOb);
$('obNext').addEventListener('click',e=>{if(obStep!==6||$('obCtrl').value!=='auto')return;const limit=Number($('obDailyLimit').value),score=Number($('obMatchThreshold').value);if(!Number.isFinite(limit)||limit<1||limit>50||!Number.isFinite(score)||score<50||score>100||!state.prefs.titles||!state.prefs.locations){e.stopImmediatePropagation();toast('Set roles, locations, a daily limit of 1–50 and a match threshold of 50–100.');return;}$('dailyLimit').value=limit;$('threshold').value=score;$('apRoles').value=state.prefs.titles;$('apLocs').value=state.prefs.locations;$('apSal').value=state.prefs.minsal||'';},true);
