const appFilters=document.createElement('div');appFilters.id='applicationFilters';appFilters.className='search-tools';appFilters.innerHTML='<label for="applicationFilterText">Find applications</label><input id="applicationFilterText" placeholder="Role, company, location or source"><label for="applicationFilterStatus">Status</label><select id="applicationFilterStatus"><option value="">All statuses</option><option>Saved</option><option>Preparing</option><option>Needs Review</option><option>Applied</option><option>Interview</option><option>Offer</option><option>Closed</option></select><label for="applicationFilterDate">Applied since (optional)</label><input id="applicationFilterDate" type="date"><button class="btn tertiary" id="clearApplicationFilters">Clear</button>';$('view-pipeline').querySelector('.product-tabs').after(appFilters);
function matches(j){const term=$('applicationFilterText').value.toLowerCase(),status=$('applicationFilterStatus').value,date=$('applicationFilterDate').value;const stage=ApplyFlowWorkspace.columnFor(j);return (!term||[j.job_title,j.title,j.company,j.location,j.loc,j.source,j.provider].filter(Boolean).join(' ').toLowerCase().includes(term))&&(!status||(status==='Closed'?['Archived','Rejected','Closed'].includes(j.stage):stage===status))&&(!date||(j.appliedAt||j.submitted_at)&&Date.parse(j.appliedAt||j.submitted_at)>=Date.parse(date));}
function filterApplications(){document.querySelectorAll('#kanban [data-card],#applicationList tr:has([data-product-app])').forEach(row=>{const id=row.dataset.card||row.querySelector('[data-product-app]')?.dataset.productApp;const j=findJob(id);row.hidden=!!j&&!matches(j);});}
['applicationFilterText','applicationFilterStatus','applicationFilterDate'].forEach(id=>$(id).addEventListener('input',filterApplications));$('clearApplicationFilters').onclick=()=>{['applicationFilterText','applicationFilterStatus','applicationFilterDate'].forEach(id=>$(id).value='');filterApplications();};const board=renderKanban;renderKanban=function(){board();filterApplications();};new MutationObserver(filterApplications).observe($('applicationList'),{childList:true});
